import json
import os

transcript_path = r"C:\Users\renu5\.gemini\antigravity\brain\2d18fb0d-4e24-45aa-b4fb-491ce2307154\.system_generated\logs\transcript_full.jsonl"
output_path = r"C:\Users\renu5\.gemini\antigravity\brain\2d18fb0d-4e24-45aa-b4fb-491ce2307154\full_conversation_history.md"

md_content = ["# Full Conversation History\n"]

with open(transcript_path, 'r', encoding='utf-8') as f:
    for line in f:
        if not line.strip():
            continue
        try:
            step = json.loads(line)
        except json.JSONDecodeError:
            continue

        source = step.get('source')
        step_type = step.get('type')
        content = step.get('content', '')

        if source == "USER_EXPLICIT" and step_type == "USER_INPUT":
            if "<USER_REQUEST>" in content and "</USER_REQUEST>" in content:
                user_req = content.split("<USER_REQUEST>")[1].split("</USER_REQUEST>")[0].strip()
                md_content.append(f"## User Prompt\n\n{user_req}\n")
            else:
                md_content.append(f"## User Prompt\n\n{content}\n")

        elif source == "MODEL" and step_type == "PLANNER_RESPONSE":
            if content:
                md_content.append(f"## AI Response\n\n{content}\n")

            tool_calls = step.get('tool_calls', [])
            for tc in tool_calls:
                name = tc.get('name')
                args = tc.get('args', {})

                if name == "ask_question":
                    q_str = args.get('questions', '[]')
                    try:
                        questions = json.loads(q_str)
                    except:
                        # Sometimes args are not doubly serialized in transcript_full
                        questions = q_str if isinstance(q_str, list) else []

                    for q in questions:
                        q_text = q.get('question', '')
                        options = q.get('options', [])
                        md_content.append(f"### Question Asked by AI\n\n**{q_text}**\n")
                        for opt in options:
                            md_content.append(f"- {opt}\n")
                        md_content.append("\n")
                elif name == "write_to_file":
                    target_file = args.get('TargetFile', '')
                    if isinstance(target_file, str) and target_file.startswith('"') and target_file.endswith('"'):
                        try:
                            target_file = json.loads(target_file)
                        except:
                            pass

                    if target_file:
                        link = f"[{os.path.basename(target_file)}](file:///{target_file.replace(chr(92), '/')})"
                        md_content.append(f"### File Created by AI\n\nGenerated file: {link}\n")

        elif source == "MODEL" and step_type == "ASK_QUESTION":
            md_content.append(f"## User Answers to Questions\n\n{content}\n")

with open(output_path, 'w', encoding='utf-8') as f:
    f.write("\n".join(md_content))

print(f"Generated {output_path}")
